import 'package:flutter/material.dart';import 'package:flutter_bloc/flutter_bloc.dart';import '../../../../Core/Utils/Extensions/widget_extension.dart';import '../manager/main_cubit.dart';import '../widgets/build_bottom_navigation_bar.dart';class MainScreen extends StatelessWidget {  const MainScreen({super.key});  @override  Widget build(BuildContext context) {    return BlocProvider(      create: (context) => MainCubit(),      child: BlocBuilder<MainCubit, int>(        builder: (context, state) {          return Scaffold(            body: (context.read<MainCubit>().listScreens())                .stylePageWithCustomScroll,            bottomNavigationBar: BuildBottomNavigationBar(),            resizeToAvoidBottomInset: true,          );        },      ),    );  }}